import{_ as t,o as e,c as o,a6 as r}from"./chunks/framework.De615z8S.js";const p=JSON.parse('{"title":"Amazon主图与副图：一步一步制作","description":"","frontmatter":{"id":"amazon-listing","title":"Amazon主图与副图：一步一步制作","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","rembg","birefnet","ecommerce-image-toolkit","visual-copywriting"],"platform_rule_ids":["amazon"],"order":23.1},"headers":[],"relativePath":"ecommerce/amazon-listing.md","filePath":"ecommerce/amazon-listing.md"}'),i={name:"ecommerce/amazon-listing.md"};function d(n,a,l,s,m,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="amazon主图与副图-一步一步制作" tabindex="-1">Amazon主图与副图：一步一步制作 <a class="header-anchor" href="#amazon主图与副图-一步一步制作" aria-label="Permalink to &quot;Amazon主图与副图：一步一步制作&quot;">​</a></h1><p>本教程以DN01普通收纳盒为练习，面向Amazon US商品页。先核对具体类目和图片位置；服饰等有特殊要求的类目不能直接照搬。案例数据见<a href="/ai-visual-creation-handbook/ecommerce/cross-border">总流程</a>。</p><h2 id="先准备素材和规格记录" tabindex="-1">先准备素材和规格记录 <a class="header-anchor" href="#先准备素材和规格记录" aria-label="Permalink to &quot;先准备素材和规格记录&quot;">​</a></h2><p>准备真实商品正面、开盖、细节照片，发货清单与外尺寸。记录“主图／副图、站点、类目、当前官方出处、核对日期、导出要求”。Amazon公开摄影指南提供白底、主体占幅和文件建议；它是公开指导，不替代当前类目后台规则。<a href="https://sell.amazon.com/blog/product-photos" target="_blank" rel="noreferrer">官方摄影指南</a>。</p><p>练习母版选2000×2000像素方图，属于本教程的制作建议。生成工具只支持其他像素时记录实际结果，再通过合成或裁切完成目标版式；放大不能补回不存在的真实细节。</p><h2 id="第1步-做白底主图" tabindex="-1">第1步：做白底主图 <a class="header-anchor" href="#第1步-做白底主图" aria-label="Permalink to &quot;第1步：做白底主图&quot;">​</a></h2><ol><li>挑一张能看清完整盒体、盖子与发货内容的实拍；主体必须来自这一张真实素材。</li><li>抠图后放入纯白画布，避免灰色渐变、纹理、装饰物与宣传标签。真实商品自身标识保留。</li><li>主体放大到清晰可识别、四边不被裁切；用当前规则检查占幅，不能只看模型写了什么。</li><li>对照原照片检查边缘、颜色、透明或反光区域。阴影不改变商品结构，不画出不存在的配件。</li><li>使用<a href="/ai-visual-creation-handbook/prompts/P10">P10白底主图</a>；如果模型保不住主体，就只做背景／处理方案，再用真实商品层合成。</li></ol><p>DN01的文具是场景道具，不出现在主图发货展示中。没有清晰照片时先补拍，不能从风格图借一个相似商品。</p><h2 id="第2步-规划副图职责" tabindex="-1">第2步：规划副图职责 <a class="header-anchor" href="#第2步-规划副图职责" aria-label="Permalink to &quot;第2步：规划副图职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图片</th><th>DN01练习任务</th><th>要补的素材</th></tr></thead><tbody><tr><td>场景</td><td>放在书桌上说明用途</td><td>真实主体＋获准文具道具</td></tr><tr><td>结构</td><td>开盖与可拆隔板</td><td>开盖、隔板实拍</td></tr><tr><td>尺寸</td><td>长宽高与单位</td><td>外尺寸记录；不能画内尺寸</td></tr><tr><td>发货</td><td>盒体、盖子、隔板数量</td><td>包装／配件清单及照片</td></tr><tr><td>使用</td><td>打开、放文具、合盖</td><td>实际动作或可信步骤依据</td></tr></tbody></table><p>用<a href="/ai-visual-creation-handbook/prompts/P11">P11</a>先生成逐张简报，不一次生成完整拼贴。照片未显示的背面或结构列待补；准确短文案独立排版。尺寸图使用<a href="/ai-visual-creation-handbook/prompts/P18">P18</a>，不要套用服装通用尺码表。</p><h2 id="第3步-导出与实际页面检查" tabindex="-1">第3步：导出与实际页面检查 <a class="header-anchor" href="#第3步-导出与实际页面检查" aria-label="Permalink to &quot;第3步：导出与实际页面检查&quot;">​</a></h2><p>主图、副图单独命名并按顺序排列。核对实际像素、格式、体积、主体与文字；看缩略图是否一眼辨认。上传后查看桌面与手机实际商品页、裁切和变体对应，后台结果留记录。</p><p>本教程尚未进行Amazon后台上传。某个脚本给出PASS只能说明它检查了指定字段，不能代替商品真实性、类目要求和平台审核。</p>',14)])])}const _=t(i,[["render",d]]);export{p as __pageData,_ as default};
